type Config = { walkingSpeed?: number; dashDistance?: number; cooldownTicks?: number; initialCooldownTicks?: number };
type Input = { buttons?: number; sourceBodyWidth?: number };
type State = { cooldown: number; remaining: number; dashDirX: number; dashDirY: number; facingX: number; facingY: number; prevButtons: number; [key: string]: unknown };
const DEFAULTS = { walkingSpeed: 2, dashDistance: 60, cooldownTicks: 25, initialCooldownTicks: 10 };
const DASH_FRAMES = 8;
function cfg(config?: Config) { const c = config || {}; return { walkingSpeed: Number.isFinite(c.walkingSpeed as number) ? Number(c.walkingSpeed) : DEFAULTS.walkingSpeed, dashDistance: Number.isFinite(c.dashDistance as number) ? Number(c.dashDistance) : DEFAULTS.dashDistance, cooldownTicks: Number.isFinite(c.cooldownTicks as number) ? Math.trunc(Number(c.cooldownTicks)) : DEFAULTS.cooldownTicks, initialCooldownTicks: Number.isFinite(c.initialCooldownTicks as number) ? Math.trunc(Number(c.initialCooldownTicks)) : DEFAULTS.initialCooldownTicks }; }
function intOr(v: unknown, d: number): number { const n = Number(v); return Number.isFinite(n) ? Math.trunc(n) : d; }
function numOr(v: unknown, d: number): number { const n = Number(v); return Number.isFinite(n) ? n : d; }
export function init(config?: Config): State { const c = cfg(config); return { cooldown: c.initialCooldownTicks, remaining: 0, dashDirX: 1, dashDirY: 0, facingX: 1, facingY: 0, prevButtons: 0 }; }
export function step(state: State, input: Input, config?: Config) {
  const c = cfg(config);
  const s: State = { ...(state || ({} as State)), cooldown: Math.max(0, intOr(state && state.cooldown, c.initialCooldownTicks)), remaining: Math.max(0, intOr(state && state.remaining, 0)), dashDirX: numOr(state && state.dashDirX, 1), dashDirY: numOr(state && state.dashDirY, 0), facingX: numOr(state && state.facingX, 1), facingY: numOr(state && state.facingY, 0), prevButtons: intOr(state && state.prevButtons, 0) };
  const buttons = intOr(input && input.buttons, 0) & 255;
  const ix = ((buttons & 32) ? 1 : 0) - ((buttons & 16) ? 1 : 0);
  const iy = ((buttons & 128) ? 1 : 0) - ((buttons & 64) ? 1 : 0);
  const len = Math.hypot(ix, iy);
  const ux = len > 0 ? ix / len : 0; const uy = len > 0 ? iy / len : 0;
  const dashSpeed = c.dashDistance / DASH_FRAMES;
  const events: string[] = []; let x = 0; let y = 0; let ownsMotion = false;
  const xHeld = (buttons & 1) !== 0;
  if (s.remaining > 0) {
    x = s.dashDirX * dashSpeed; y = s.dashDirY * dashSpeed; ownsMotion = true;
    s.remaining -= 1; if (s.remaining === 0) events.push("dash-end");
  } else {
    if (s.cooldown > 0) s.cooldown -= 1;
    if (xHeld && s.cooldown === 0) {
      let dx = ux; let dy = uy;
      if (len === 0) { dx = 1; dy = 0; }
      s.dashDirX = dx; s.dashDirY = dy;
      s.cooldown = c.cooldownTicks; s.remaining = DASH_FRAMES - 1;
      x = dx * dashSpeed; y = dy * dashSpeed; ownsMotion = true; events.push("dash-start");
    } else {
      x = ux * c.walkingSpeed; y = uy * c.walkingSpeed;
    }
  }
  s.prevButtons = buttons;
  return { state: s, output: { ownsMotion, displacement: { x, y }, events } };
}

