export function init(config) {
  const c = config || {};
  return {
    cooldown: (c.initialCooldownTicks != null ? c.initialCooldownTicks : 10) | 0,
    remaining: 0,
    dirX: 0,
    dirY: 0,
    faceX: 1,
    faceY: 0,
    prevButtons: 0
  };
}

export function step(state, input, config) {
  const c = config || {};
  const walk = c.walkingSpeed != null ? c.walkingSpeed : 2;
  const dashDistance = c.dashDistance != null ? c.dashDistance : 60;
  const cooldownTicks = c.cooldownTicks != null ? c.cooldownTicks : 25;
  const buttons = (input && input.buttons) ? input.buttons | 0 : 0;
  const s = {
    cooldown: state && state.cooldown != null ? state.cooldown | 0 : 0,
    remaining: state && state.remaining != null ? state.remaining | 0 : 0,
    dirX: state && state.dirX ? state.dirX : 0,
    dirY: state && state.dirY ? state.dirY : 0,
    faceX: state && state.faceX != null ? state.faceX : 1,
    faceY: state && state.faceY != null ? state.faceY : 0,
    prevButtons: state && state.prevButtons ? state.prevButtons | 0 : 0
  };
  const events = [];
  let dx = 0;
  let dy = 0;
  let ownsMotion = false;
  const ix = ((buttons & 32) ? 1 : 0) - ((buttons & 16) ? 1 : 0);
  const iy = ((buttons & 128) ? 1 : 0) - ((buttons & 64) ? 1 : 0);
  const perFrame = dashDistance / 8;

  if (s.remaining > 0) {
    dx = s.dirX * perFrame;
    dy = s.dirY * perFrame;
    ownsMotion = true;
    s.remaining -= 1;
    if (s.remaining === 0) events.push("dash-end");
  } else if ((buttons & 1) !== 0 && s.cooldown === 0) {
    let ux = ix;
    let uy = iy;
    if (ux === 0 && uy === 0) { ux = s.faceX; uy = s.faceY; }
    const len = Math.sqrt(ux * ux + uy * uy) || 1;
    s.dirX = ux / len;
    s.dirY = uy / len;
    s.cooldown = cooldownTicks | 0;
    dx = s.dirX * perFrame;
    dy = s.dirY * perFrame;
    ownsMotion = true;
    s.remaining = 7;
    events.push("dash-start");
  } else {
    if (ix !== 0 || iy !== 0) {
      const len = Math.sqrt(ix * ix + iy * iy);
      dx = ix / len * walk;
      dy = iy / len * walk;
      s.faceX = ix;
      s.faceY = iy;
    }
    if (s.cooldown > 0) s.cooldown -= 1;
  }
  s.prevButtons = buttons;
  return { state: s, output: { ownsMotion: ownsMotion, displacement: { x: dx, y: dy }, events: events } };
}
